    <div class="phone">
        <div class="screen">
            <div class="view">
                <div class="video-call-container">
                    <div class="flipper" id="flipper">
                        <div class="video-front">
                            <div class="dialogue-overlay">
                                <p id="dialogue-text">$1</p>
                                <div class="dialogue-nav">
                                    <button id="prev-btn" class="nav-button" title="上一条"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M15.41 7.41L14 6l-6 6 6 6 1.41-1.41L10.83 12z"></path></svg></button>
                                    <span id="dialogue-counter"></span>
                                    <button id="next-btn" class="nav-button" title="下一条"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M10 6L8.59 7.41 13.17 12l-4.58 4.59L10 18l6-6z"></path></svg></button>
                                </div>
                            </div>
                        </div>
                        <div class="video-back">
                            <div class="image-border-box">
                                <div id="text-wrapper"><p>$2</p></div>
                            </div>
                        </div>
                    </div>
                    <div class="static-overlay">
                        <div class="top-bar"><div class="timer-assembly"><span id="call-timer">00:00</span></div></div>
                        <div class="self-view-container"><div class="self-view user_avatar"></div></div>
                    </div>
                    <div class="end-call-button-container" id="end-call-container"><button id="end-call-btn">结束通话</button></div>
                </div>
            </div>
            <div class="top-bar-container">
                <div class="status-bar"><div class="battery"><div class="battery-icon"><span id="battery-percent">85</span><div id="battery-level" class="battery-level"></div></div></div></div>
                <div class="notch"><div class="speaker"></div><div class="camera"></div></div>
            </div>
        </div>
    </div>
    <div class="reply-modal-overlay" id="reply-modal"><div class="reply-window"><textarea id="reply-input" placeholder="想对我说什么..."></textarea><div class="reply-actions"><button class="reply-button cancel">取消</button><button class="reply-button send">发送</button></div></div></div>
    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const characterName = '$3';
            const body = document.body;
            const callContainer = document.querySelector('.video-call-container');
            const flipper = document.getElementById('flipper');
            const timerElement = document.getElementById('call-timer');
            const endCallContainer = document.getElementById('end-call-container');
            const setBattery = () => {
                const batteryLevel = 85;
                document.getElementById('battery-percent').textContent = batteryLevel;
                document.getElementById('battery-level').style.width = `${batteryLevel}%`;
            };

            // --- DIALOGUE NAVIGATION LOGIC ---
            const dialogueTextEl = document.getElementById('dialogue-text');
            const prevBtn = document.getElementById('prev-btn');
            const nextBtn = document.getElementById('next-btn');
            const counterEl = document.getElementById('dialogue-counter');
            const navContainer = document.querySelector('.dialogue-nav');
            const dialogueOverlay = document.querySelector('.dialogue-overlay');

            let dialogues = [];
            let currentIndex = 0;
            const dialoguesRaw = dialogueTextEl.textContent;
            dialogues = dialoguesRaw.split('|||').map(d => d.trim()).filter(d => d.length > 0);

            const updateDialogueDisplay = () => {
                if (!dialogues || dialogues.length === 0) {
                    dialogueTextEl.textContent = '...';
                    if (navContainer) navContainer.style.display = 'none';
                    return;
                }
                dialogueTextEl.textContent = dialogues[currentIndex];
                if (dialogues.length > 1) {
                    if (navContainer) navContainer.style.display = 'flex';
                    if (counterEl) counterEl.textContent = `${currentIndex + 1} / ${dialogues.length}`;
                    if (prevBtn) prevBtn.disabled = (currentIndex === 0);
                    if (nextBtn) nextBtn.disabled = (currentIndex === dialogues.length - 1);
                } else {
                    if (navContainer) navContainer.style.display = 'none';
                }
            };

            if (prevBtn && nextBtn) {
                prevBtn.addEventListener('click', e => { e.stopPropagation(); if (currentIndex > 0) { currentIndex--; updateDialogueDisplay(); } });
                nextBtn.addEventListener('click', e => { e.stopPropagation(); if (currentIndex < dialogues.length - 1) { currentIndex++; updateDialogueDisplay(); } });
            }
            updateDialogueDisplay();
            // --- END OF DIALOGUE LOGIC ---

            const replyModal = document.getElementById('reply-modal');
            const replyCancelBtn = replyModal.querySelector('.cancel');
            const replySendBtn = replyModal.querySelector('.send');
            const replyInput = document.getElementById('reply-input');

            dialogueOverlay.addEventListener('click', (event) => { event.stopPropagation(); body.classList.add('reply-active'); replyInput.focus(); });
            function closeReplyModal() { body.classList.remove('reply-active'); }
            replyCancelBtn.addEventListener('click', closeReplyModal);
            replySendBtn.addEventListener('click', () => { const message = replyInput.value.trim(); if (message && typeof triggerSlash === 'function') { triggerSlash(`/send 和${characterName}视频通话：${message}|/trigger`); } replyInput.value = ''; closeReplyModal(); });
            replyModal.addEventListener('click', (event) => { if (event.target === replyModal) { closeReplyModal(); } });
            flipper.addEventListener('click', () => { if (!body.classList.contains('reply-active')) { callContainer.classList.toggle('is-flipped'); } });

            let seconds = 0;
            const callTimerInterval = setInterval(() => { seconds++; const mins = String(Math.floor(seconds / 60)).padStart(2, '0'); const secs = String(seconds % 60).padStart(2, '0'); timerElement.textContent = `${mins}:${secs}`; }, 1000);
            endCallContainer.addEventListener('click', (event) => { event.stopPropagation(); clearInterval(callTimerInterval); if (typeof triggerSlash === 'function') { const duration = timerElement.textContent.trim(); triggerSlash(`/send 回复和${characterName}的聊天：通话结束，时长${duration}|/trigger`); } });
            setBattery();
        });
    </script>
</body>
</html>
