            </div>
            <div id="list-view" class="view">
                <div class="list-header"><h1>消息</h1></div>
                <div id="message-list-container" class="message-list"></div>
            </div>
        </div>
    </div>

    <div id="edit-avatar-modal" class="modal-overlay">
        <div class="modal-content">
            <h2 id="modal-title" class="modal-title">更换头像</h2>
            <input id="avatar-url-input" type="text" class="modal-input" placeholder="输入图片链接...">
            <div class="modal-actions">
                <button id="cancel-avatar-btn" class="modal-btn modal-btn-cancel">取消</button>
                <button id="confirm-avatar-btn" class="modal-btn modal-btn-confirm">确认</button>
            </div>
        </div>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const $ = (id) => document.getElementById(id);

            // 设置电池显示
            const setBattery = () => { 
                $('battery-percent').textContent = '85'; 
                $('battery-level').style.width = '85%'; 
            };
            setBattery();

            // 解析消息数据
            const listContainer = $('message-list-container');
            const rawDataContainer = $('raw-message-list-data');
            const listData = rawDataContainer ? rawDataContainer.innerHTML : '';

            // 生成消息列表HTML
            const entryRegex = /\(([^|]+)\|([^|]+)\|([^|]+)\|([^|]+)\|([\d+]+)\)/g;
            let match;
            let listHTML = '';

            while ((match = entryRegex.exec(listData)) !== null) {
                const [fullMatch, type, name, message, time, unread] = match;
                listHTML += `
                    <div class="chat-item-wrapper" data-name="${name}" data-type="${type}">
                        <div class="chat-item-actions"><div class="edit-btn">编辑</div></div>
                        <div class="chat-item">
                            <div class="avatar"></div>
                            <div class="chat-info">
                                <div class="chat-name">${name}</div>
                                <div class="last-message">${message}</div>
                            </div>
                            <div class="chat-meta">
                                <div class="timestamp">${time}</div>
                                <div class="unread-badge ${unread === '0' ? 'hidden' : ''}">${unread}</div>
                            </div>
                        </div>
                    </div>`;
            }
            listContainer.innerHTML = listHTML;

            // 设置头像
            const avatarColors = ['#FF9500', '#FF2D55', '#AF52DE', '#5856D6', '#007AFF', '#34C759', '#FF3B30', '#5AC8FA'];

            function setAvatar(itemWrapper) {
                const name = itemWrapper.dataset.name;
                const avatar = itemWrapper.querySelector('.avatar');
                if (!name || !avatar) return;

                const savedAvatarUrl = localStorage.getItem(`avatar_${name}`);
                if (savedAvatarUrl) {
                    avatar.style.backgroundImage = `url('${savedAvatarUrl}')`;
                    avatar.textContent = ''; 
                    avatar.classList.add('has-image');
                } else {
                    avatar.style.backgroundImage = ''; 
                    avatar.textContent = name.charAt(0).toUpperCase(); 
                    avatar.classList.remove('has-image');

                    let hash = 0; 
                    for (let i = 0; i < name.length; i++) { 
                        hash = name.charCodeAt(i) + ((hash << 5) - hash); 
                    }
                    const colorIndex = Math.abs(hash % avatarColors.length);
                    avatar.style.backgroundColor = avatarColors[colorIndex];
                }
            }

            document.querySelectorAll('.chat-item-wrapper').forEach(setAvatar);

            // 头像编辑功能
            const editModal = $("edit-avatar-modal"),
                  editModalTitle = $("modal-title"),
                  urlInput = $("avatar-url-input"),
                  confirmBtn = $("confirm-avatar-btn"),
                  cancelBtn = $("cancel-avatar-btn");

            let currentEditingName = null;

            function openEditModal(name) {
                currentEditingName = name;
                editModalTitle.textContent = `更换 ${name} 的头像`;
                urlInput.value = localStorage.getItem(`avatar_${name}`) || "";
                editModal.classList.add("visible");
            }

            function closeEditModal() {
                editModal.classList.remove("visible");
            }

            confirmBtn.addEventListener("click", () => {
                if (!currentEditingName) return;

                const url = urlInput.value.trim();
                const item = document.querySelector(`.chat-item-wrapper[data-name="${currentEditingName}"]`);

                if (url) {
                    localStorage.setItem(`avatar_${currentEditingName}`, url);
                } else {
                    localStorage.removeItem(`avatar_${currentEditingName}`);
                }

                if (item) setAvatar(item);
                closeEditModal();
            });

            cancelBtn.addEventListener("click", closeEditModal);
            editModal.addEventListener("click", e => {
                if (e.target === editModal) {
                    closeEditModal();
                }
            });

            // 滑动功能
            let activeSwipeWrapper = null;

            function handleItemClick(item) {
                const type = item.dataset.type;
                const name = item.dataset.name;

                if (typeof triggerSlash === 'function') {
                    if (name === "公众号") {
                        triggerSlash("/send 查看公众号");
                    } else if (name === "通知中心") {
                        triggerSlash("/send 查看通知中心");
                    } else if (type === "私聊" || type === "群聊") {
                        triggerSlash(`/send 查看和${name}的聊天`);
                    }
                }
            }

            function setupSwipe(wrapper) {
                const item = wrapper.querySelector(".chat-item");
                const swipeDistance = 80;

                let startX, currentX, isDragging = false, isSwiping = false;

                const startDrag = (e) => {
                    if (e.target.closest(".edit-btn")) return;

                    startX = e.pageX || e.touches[0].pageX;
                    isDragging = true;
                    isSwiping = false;
                    item.style.transition = "none";
                };

                const duringDrag = (e) => {
                    if (!isDragging) return;

                    currentX = e.pageX || e.touches[0].pageX;
                    const diff = currentX - startX;

                    if (Math.abs(diff) > 10) {
                        isSwiping = true;
                    }

                    if (item.classList.contains("swiped") && diff > 0) {
                        item.style.transform = `translateX(${-swipeDistance + diff}px)`;
                    } else if (!item.classList.contains("swiped") && diff < 0) {
                        item.style.transform = `translateX(${diff}px)`;
                    }
                };

                const endDrag = (e) => {
                    isDragging = false;
                    item.style.transition = "transform 0.3s ease-out";

                    if (isSwiping) {
                        const diff = currentX - startX;
                        const threshold = swipeDistance / 2;

                        if (item.classList.contains("swiped")) {
                            if (diff > threshold) {
                                resetSwipe(wrapper);
                            } else {
                                item.style.transform = `translateX(-${swipeDistance}px)`;
                            }
                        } else if (diff < -threshold) {
                            if (activeSwipeWrapper && activeSwipeWrapper !== wrapper) {
                                resetSwipe(activeSwipeWrapper);
                            }

                            item.style.transform = `translateX(-${swipeDistance}px)`;
                            item.classList.add("swiped");
                            activeSwipeWrapper = wrapper;
                        } else {
                            resetSwipe(wrapper);
                        }
                    }
                };

                item.addEventListener("click", (e) => {
                    if (isSwiping) {
                        e.preventDefault();
                        e.stopPropagation();
                    } else {
                        handleItemClick(wrapper);
                    }
                });

                item.addEventListener("mousedown", startDrag);
                document.addEventListener("mousemove", duringDrag);
                document.addEventListener("mouseup", endDrag);

                item.addEventListener("touchstart", startDrag, { passive: true });
                document.addEventListener("touchmove", duringDrag, { passive: false });
                document.addEventListener("touchend", endDrag);

                wrapper.querySelector(".edit-btn").addEventListener('click', () => {
                    openEditModal(wrapper.dataset.name);
                    if (activeSwipeWrapper) resetSwipe(activeSwipeWrapper);
                });
            }

            function resetSwipe(wrapper) {
                if (!wrapper) return;

                const item = wrapper.querySelector(".chat-item");
                item.style.transform = "translateX(0)";
                item.classList.remove("swiped");

                if (activeSwipeWrapper === wrapper) {
                    activeSwipeWrapper = null;
                }
            }

            document.querySelectorAll(".chat-item-wrapper").forEach(setupSwipe);

            document.addEventListener("click", e => {
                if (activeSwipeWrapper && !activeSwipeWrapper.contains(e.target)) {
                    resetSwipe(activeSwipeWrapper);
                }
            }, true);
        });
    </script>
</body>
